27	bool TikcppDataCopyCheck::CheckDataCopyAlign(uint64_t addr, uint8_t pos, bool isSrc)
28	{
29	    // gm is 1 Byte aligned, so do not need to check aligned
30	    uint32_t dataType = (isSrc ? param_.srcDtypeBytes : param_.dstDtypeBytes);
31	    std::map<Hardware, uint32_t> alignSizeMap = {
32	        {Hardware::GM, 1},
33	        {Hardware::L1, 32},
34	        {Hardware::UB, 32},
35	        {Hardware::L0A, 512 * ((dataType + 1) / sizeof(uint16_t))},
36	        {Hardware::L0B, 512 * ((dataType + 1) / sizeof(uint16_t))},
37	        {Hardware::L0C, 512 * ((dataType + 1) / sizeof(uint16_t))},
38	        {Hardware::BIAS, 64},
39	    };
40	
41	    if (pos != static_cast<uint8_t>(Hardware::GM)) {
42	        uint32_t alignBytes = alignSizeMap[static_cast<Hardware>(pos)];
43	        if (isSrc) {
44	            ASCENDC_CHECK(CheckTensorAddrAlign(addr, pos, alignBytes, "src"));
45	        } else {
46	            ASCENDC_CHECK(CheckTensorAddrAlign(addr, pos, alignBytes, "dst"));
47	        }
48	    }
49	    return true;
50	}
51	bool TikcppDataCopyCheck::CheckAddrAlign()
52	{
53	    bool retSrc = CheckDataCopyAlign(param_.srcAddr, param_.srcPos, true);
54	    bool retDst = CheckDataCopyAlign(param_.dstAddr, param_.dstPos, false);
55	    return retSrc && retDst;
56	}
57	} // namespace check
58	} // namespace AscendC
