24	// extract total element num in each repeat. Used in normal mode
25	uint64_t GetMaskLength(std::vector<uint64_t>& maskArray, const uint32_t dtypeSize)
26	{
27	    uint64_t maskLen = 0;
28	    if (maskArray[static_cast<int32_t>(CommonParams::MASK_HIGH_IDX)] == 0) {
29	        // get last element index in mask_low_idx
30	        for (uint32_t i = 0; i < static_cast<uint32_t>(CommonParams::MASK_MAX_ELE_LEN); ++i) {
31	            if ((maskArray[static_cast<int32_t>(CommonParams::MASK_LOW_IDX)] & (CONST_MASK_VALUE >> i)) != 0) {
32	                maskLen = static_cast<uint64_t>(CommonParams::MASK_MAX_ELE_LEN) - static_cast<uint64_t>(i);
33	                break;
34	            }
35	        }
36	    } else {
37	        // get last element index in mask_high_idx, then add 64
38	        for (uint32_t i = 0; i < static_cast<uint32_t>(CommonParams::MASK_MAX_ELE_LEN); ++i) {
39	            if ((maskArray[static_cast<int32_t>(CommonParams::MASK_HIGH_IDX)] & (CONST_MASK_VALUE >> i)) != 0) {
40	                maskLen = static_cast<uint64_t>(CommonParams::MASK_MAX_ELE_LEN) +
41	                          static_cast<uint64_t>(CommonParams::MASK_MAX_ELE_LEN) - static_cast<uint64_t>(i);
42	                break;
43	            }
44	        }
45	    }
46	    if (dtypeSize >= sizeof(uint32_t)) {
47	        uint64_t maxElePerRep = DEFAULT_BLOCK_SIZE / dtypeSize;
48	        maskLen = (maskLen >= maxElePerRep) ? maxElePerRep : maskLen;
49	    }
50	    return maskLen;
51	}
