84	bool TikcppBaseCheck::UpdateMaskArrayAndCheck(std::vector<uint64_t>& maskArray, const uint32_t maxByteLen) const
85	{
86	    // do not use mask given by user, use mask value stored in registers
87	    if (!MaskSetter::Instance().GetMask()) {
88	        maskArray = {ModelFactoryGetMaskHigh(), ModelFactoryGetMaskLow()};
89	        CHECK_LOG_INFO(
90	            "Due to isSetMask = false, maskArray is changed to maskHigh %lu, maskLow %lu.", ModelFactoryGetMaskHigh(),
91	            ModelFactoryGetMaskLow());
92	    }
93	    MaskSetter::Instance().SetMask(true);
94	    if (maxByteLen >= sizeof(int32_t) && maskArray.size() == 2) { // when size 2 need to update maskHigh
95	        // Example: mask[64, 64] but dtype is float, maximum only read 1 64. maskHigh is unused, need to set to 0.
96	        maskArray[0] = 0; // in counter / norm mode, both maskHigh is in fact 0
97	    }
98	    if (maskArray.size() != 1 && maskArray.size() != 2) { // mask = len 1, mask[2] = len 2
99	        ASCENDC_CHECK_AND_LOG(
100	            false, { CHECK_LOG_ERROR("maskArray size is %lu, which should be 1 or 2.", maskArray.size()); });
101	    } else if (maskArray.size() == 1) {
102	        // when norm mode, update mask value to <= 128 when array size is 1
103	        if (ModelFactoryGetMaskMode() == 0) {
104	            uint64_t maxElePerRep = DEFAULT_BLOCK_SIZE / maxByteLen;
105	            maskArray[0] = std::min(maskArray[0], maxElePerRep);
106	        }
107	        ASCENDC_CHECK_AND_LOG(CheckMaskImm(maskArray[0]), {
108	            CHECK_LOG_ERROR(
109	                "When maskArray size is 1, mask value %lu "
110	                "is invalid",
111	                maskArray[0]);
112	        });
113	    } else {
114	        ASCENDC_CHECK_AND_LOG(CheckMaskArray(maskArray), {
115	            CHECK_LOG_ERROR(
116	                "When maskArray size is 2, maskHigh %lu, "
117	                "maskLow %lu is invalid",
118	                maskArray[0], maskArray[1]);
119	        });
120	    }
121	    return true;
