161	bool TikcppBaseCheck::CheckMaskArray(std::vector<uint64_t> maskArray) const
162	{
163	    // counter mode
164	    if (ModelFactoryGetMaskMode() == 1) {
165	        if (maskArray[1] > CONST_UINT32_MAX) { // only use maskLow[0:32] as counter mask. Only give warning!
166	            CHECK_LOG_WARNING(
