197	    }
198	    // normal mode
199	#if defined(__NPU_ARCH__) && (__NPU_ARCH__ == 1001 || __NPU_ARCH__ == 2002)
200	    ASCENDC_CHECK_AND_LOG(mask != 0ULL, {
201	        CHECK_LOG_ERROR(
202	            "During calculation in normal mode in Ascend910 / Ascend310p "
203	            "/ Ascend610, mask %lu cannot be 0.",
204	            mask);
205	    });
206	#endif
