210	// when counter mode, split into norm mode with main block and tail block
211	void CounterSplitMainTail(
212	    std::vector<uint64_t>& maskArray, const uint32_t dtypeBytes, uint64_t& mainRepeatTimes, uint64_t& tailRepeatTimes,
213	    std::vector<uint64_t>& mainMaskArray, std::vector<uint64_t>& tailMaskArray)
214	{
215	    uint32_t oneRepeatNum = ONE_REPEAT_BYTE_SIZE / dtypeBytes;                   // when counter mode, always full mask
216	    uint64_t elementNum = (maskArray.size() == 1) ? maskArray[0] : maskArray[1]; // maskLow means element num
217	    mainRepeatTimes = elementNum / oneRepeatNum;
218	    uint64_t tailEleNum = elementNum % oneRepeatNum;
219	    tailRepeatTimes = (tailEleNum == 0) ? 0 : 1;
220	    mainMaskArray = {oneRepeatNum};
221	    tailMaskArray = {tailEleNum};
222	}
223	
224	// calculate max extent, aka the offset of the end of all effective element
225	// maskLen: each repeat calculate the first maskLen elements
226	// blockLen: element num per block
227	// return: in unit of element
228	uint64_t CalculateVectorMaxOffset(
229	    const uint64_t repeatTimes, const uint64_t blkStride, const uint64_t repStride, const uint64_t maskLen,
230	    const uint64_t blockLen)
231	{
232	    if (repeatTimes == 0) {
233	        return 0;
234	    }
235	    ASSERT(blockLen != 0);
236	    uint64_t blkNumLastRep = DivCeil(maskLen, blockLen); // last repeat needs x blocks for maskLen elements
237	    uint64_t eleNumLastBlk = ((maskLen % blockLen) != 0) ? (maskLen % blockLen) : blockLen;
238	    uint64_t maxOffset = ((repeatTimes - 1) * repStride + (blkNumLastRep - 1) * blkStride) * blockLen + eleNumLastBlk;
239	    return maxOffset;
240	}
241	
242	namespace {
243	// Given repeatTimes and stride etc, to return total buffersize needed in unit of Bytes
244	uint64_t CalculateNeededTensorSize(
245	    std::vector<uint64_t>& maskArray, const uint32_t dtypeBytes, const uint64_t repeatTimes, const uint64_t blkStride,
246	    const uint64_t repStride)
247	{
248	    uint64_t maskVal = (maskArray.size() == 1) ? maskArray[0] : GetMaskLength(maskArray, dtypeBytes);
249	    ASSERT(dtypeBytes != 0);
250	    uint64_t eleNumPerBlock = static_cast<uint64_t>(PlatFormParams::ONE_BLK_SIZE) / dtypeBytes;
251	    uint64_t maxOffset = CalculateVectorMaxOffset(repeatTimes, blkStride, repStride, maskVal, eleNumPerBlock);
252	    maxOffset = maxOffset * dtypeBytes;
253	    if (Int4Setter::Instance().GetInt4()) {
254	        eleNumPerBlock = static_cast<uint64_t>(PlatFormParams::ONE_BLK_SIZE) * INT4_TWO;
255	        maxOffset = CalculateVectorMaxOffset(repeatTimes, blkStride, repStride, maskVal, eleNumPerBlock);
256	        maxOffset = maxOffset / INT4_TWO;
257	        Int4Setter::Instance().ResetInt4();
258	    }
259	    return maxOffset;
260	}
261	
262	// in counter mode, check whether the data calculated in cmd exceed the tensor size
263	// need to convert to norm mode with main block and tail block
264	bool CheckTensorOverflowLowCounter(
265	    std::vector<uint64_t>& maskArray, const TensorOverflowParams& params, const std::string& tensorName,
266	    const std::string& apiName)
267	{
268	    std::vector<uint64_t> mainMaskArray = {0};
269	    std::vector<uint64_t> tailMaskArray = {0};
270	    uint64_t mainRepeatTimes = 0;
271	    uint64_t tailRepeatTimes = 0;
272	    CounterSplitMainTail(maskArray, params.dtypeSize, mainRepeatTimes, tailRepeatTimes, mainMaskArray, tailMaskArray);
273	    // when counter mode, repeatTimes given by user is not used
274	    // Need to compare: endpoint of mainBlock VS endpoint of tailBlock
275	    // Especially scenes where blkStride is much larger than repStride. mainBlock endpoint will be larger!!
276	    uint64_t mainBlkSize =
277	        CalculateNeededTensorSize(mainMaskArray, params.dtypeSize, mainRepeatTimes, params.blkStride, params.repStride);
278	    uint64_t maxOffset = mainBlkSize;
279	    if (tailRepeatTimes > 0) { // calculate tail block from the last repStride in main block
280	        uint64_t tailRepeatStart = mainRepeatTimes * params.repStride * ONE_BLK_SIZE;
281	        uint64_t tailBlkSize = CalculateNeededTensorSize(
282	            tailMaskArray, params.dtypeSize, tailRepeatTimes, params.blkStride, params.repStride);
283	        maxOffset = std::max(mainBlkSize, tailRepeatStart + tailBlkSize);
284	    }
285	    ASCENDC_CHECK(CheckTensorSizeOverflow(maxOffset, params.bufferSize, tensorName, apiName, ModeType::COUNTER_MODE));
286	    return true;
287	}
288	
289	// in normal mode, check whether the data calculated in cmd exceed the tensor size
290	bool CheckTensorOverflowLowNorm(
291	    std::vector<uint64_t>& maskArray, const TensorOverflowParams& params, const std::string& tensorName,
292	    const std::string& apiName)
293	{
294	    uint64_t maxOffset =
295	        CalculateNeededTensorSize(maskArray, params.dtypeSize, params.repeatTimes, params.blkStride, params.repStride);
296	    ASCENDC_CHECK(CheckTensorSizeOverflow(maxOffset, params.bufferSize, tensorName, apiName, ModeType::NORM_MODE));
297	    return true;
298	}
299	
300	// in counter mode, check whether the data calculated in cmd exceed the tensor size for GatherMask
301	#if defined(__NPU_ARCH__) && ((__NPU_ARCH__ == 2201) || (__NPU_ARCH__ == 3002) || (__NPU_ARCH__ == 3102) || \
302	                              (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102))
303	bool CheckTensorOverflowLowCounterGatherMask(
304	    std::vector<uint64_t>& maskArray, const TensorOverflowParams& params, const std::string& tensorName)
305	{
306	    uint64_t maskValue = (maskArray.size() == 1) ? maskArray[0] : maskArray[1];
307	    uint64_t eleNumPerBlock = ONE_BLK_SIZE / params.dtypeSize;
308	    uint64_t blockNumPerRep = (maskValue + eleNumPerBlock - 1) / eleNumPerBlock; // total blks needed for mask num
309	    uint64_t repeatOffset = (params.repeatTimes - 1) * params.repStride * ONE_BLK_SIZE; // last repeat start pos
310	    uint64_t extraNum = blockNumPerRep * eleNumPerBlock - maskValue; // elements that do not need in tail blocks
311	    uint64_t blockOffset = ((blockNumPerRep - 1) * params.blkStride + 1) * ONE_BLK_SIZE; // endblk pos(include extraNum)
312	    uint64_t maxOffset = repeatOffset + blockOffset - extraNum * params.dtypeSize;
313	    ASCENDC_CHECK(
314	        CheckTensorSizeOverflow(maxOffset, params.bufferSize, tensorName, "GatherMask", ModeType::COUNTER_MODE));
315	    return true;
316	}
317	#endif
318	} // namespace
319	
320	// check whether the needed size overflow the allocated buffersize, the unit is bytes.
321	bool TikcppBaseCheck::CheckTensorOverflowLow(
322	    std::vector<uint64_t>& maskArray, const TensorOverflowParams& params, const std::string& tensorName) const
323	{
324	    if (ModelFactoryGetMaskMode() == 1) { // counter mode
325	        return CheckTensorOverflowLowCounter(maskArray, params, tensorName, apiName);
326	    }
327	    return CheckTensorOverflowLowNorm(maskArray, params, tensorName, apiName);
328	}
329	
330	// check whether the needed size overflow the allocated buffersize, the unit is bytes.
331	bool TikcppBaseCheck::CheckTensorOverflowLowGathermask(
332	    std::vector<uint64_t>& maskArray, const TensorOverflowParams& params, const std::string& tensorName) const
333	{
334	    if (params.isCounter) { // counter mode
335	#if defined(__NPU_ARCH__) && ((__NPU_ARCH__ == 2201) || (__NPU_ARCH__ == 3002) || (__NPU_ARCH__ == 3102) || \
336	                              (__NPU_ARCH__ == 3510) || (__NPU_ARCH__ == 5102))
337	        return CheckTensorOverflowLowCounterGatherMask(maskArray, params, tensorName);
338	#else
339	        return CheckTensorOverflowLowCounter(maskArray, params, tensorName, apiName);
340	#endif
341	    }
342	    std::vector<uint64_t> maskArrayReal = {FULL_MASK, FULL_MASK}; // when norm mode, GatherMask neglect mask
343	    return CheckTensorOverflowLowNorm(maskArrayReal, params, tensorName, apiName);
344	}
345	
346	bool TikcppBaseCheck::CheckTensorOverflowLowBrcb(
347	    const TensorOverflowParams& params, const std::string& tensorName) const
348	{
349	    std::vector<uint64_t> maskArrayReal = {FULL_MASK, FULL_MASK};
350	    return CheckTensorOverflowLowNorm(maskArrayReal, params, tensorName, apiName);
351	}
352	
353	bool TikcppBaseCheck::CheckTensorAddrAlign(
354	    const uint64_t tensorAddr, const uint8_t phyPos, const uint64_t alignBytes, const std::string& tensorInfo) const
355	{
356	    uint64_t hardwareBaseAddr = static_cast<uint64_t>(
357	        reinterpret_cast<uintptr_t>(ConstDefiner::Instance().GetHardwareBaseAddr(static_cast<Hardware>(phyPos))));
358	    uint64_t tensorAbsPos = tensorAddr - hardwareBaseAddr;
359	    ASCENDC_CHECK_AND_LOG(((tensorAbsPos % alignBytes) == 0), {
360	        CHECK_LOG_ERROR(
361	            "Failed to check %s tensor address "
362	            "alignment in %s, current tensor address is %lu, which should be %lu byte aligned.",
363	            tensorInfo.c_str(), apiName.c_str(), tensorAbsPos, alignBytes);
364	    });
365	    return true;
366	}
367	
368	} // namespace check
369	} // namespace AscendC
