21	
22	bool TikcppVecBinaryCheck::CheckCmpTensorOverflowHigh(
23	    const uint32_t dtypeSize, const uint64_t bufferSize, const uint32_t calCount, const std::string& tensorName)
24	{
25	    uint64_t needSize = static_cast<uint64_t>(dtypeSize * calCount / 8); // 1 uint8 equal to 8 bits
26	    ASCENDC_CHECK(CheckTensorSizeOverflow(needSize, bufferSize, tensorName, apiName));
27	    return true;
28	}
29	
30	static uint64_t CalculateNeededCmpTensorSize(const uint64_t repeatTimes, const uint64_t srcDtypeBytes)
31	{
32	    if (repeatTimes == 0) {
33	        return 0;
34	    }
35	    ASCENDC_CHECK(srcDtypeBytes != 0);
36	    uint64_t maxOffset = repeatTimes * static_cast<uint64_t>(PlatFormParams::ONE_REP_BYTE_SIZE) / srcDtypeBytes /
37	                         8; // 1 uint8 equal to 8 bits
38	    return maxOffset;
39	}
40	
41	bool TikcppVecBinaryCheck::CheckCmpTensorOverflowLowNorm(
42	    const TensorOverflowParams& params, const std::string& tensorName)
43	{
44	    uint64_t maxOffset = CalculateNeededCmpTensorSize(params.repeatTimes, param_.src0DtypeBytes);
45	    ASCENDC_CHECK(CheckTensorSizeOverflow(maxOffset, params.bufferSize, tensorName, apiName, ModeType::NORM_MODE));
46	    return true;
47	}
48	
49	bool TikcppVecBinaryCheck::CommonCheck()
50	{
51	    const std::string supportPos = "VECIN/VECOUT/VECCALC";
52	    ASCENDC_CHECK(CheckTensorScope(param_.dstLogicPos, static_cast<uint8_t>(HardWareIndex::UB), "dst", supportPos));
53	    ASCENDC_CHECK(CheckTensorScope(param_.src0LogicPos, static_cast<uint8_t>(HardWareIndex::UB), "src0", supportPos));
54	    ASCENDC_CHECK(CheckTensorScope(param_.src1LogicPos, static_cast<uint8_t>(HardWareIndex::UB), "src1", supportPos));
55	
56	    ASCENDC_CHECK(CheckBufferSizeOverFlow(
57	        param_.dstSize, GlobalParams::Instance().bufferSizeMap.at(param_.dstPos),
58	        "check dst tensor buffersize failed"));
59	    ASCENDC_CHECK(CheckBufferSizeOverFlow(
60	        param_.src0Size, GlobalParams::Instance().bufferSizeMap.at(param_.src0Pos),
61	        "check src0 tensor buffersize failed"));
62	    ASCENDC_CHECK(CheckBufferSizeOverFlow(
63	        param_.src1Size, GlobalParams::Instance().bufferSizeMap.at(param_.src1Pos),
64	        "check src1 tensor buffersize failed"));
65	    ASCENDC_CHECK(CheckAddrAlign());
66	    return true;
67	}
68	
69	bool TikcppVecBinaryCheck::CheckAllLowLevel(std::vector<uint64_t> maskArray)
70	{
71	    uint32_t maxByteLen = std::max(std::max(param_.dstDtypeBytes, param_.src0DtypeBytes), param_.src1DtypeBytes);
72	    ASCENDC_CHECK(UpdateMaskArrayAndCheck(maskArray, maxByteLen));
73	    ASCENDC_CHECK(CommonCheck());
74	
75	    TensorOverflowParams params = {
76	        param_.dstSize,
77	        param_.dstDtypeBytes,
78	        static_cast<uint64_t>(param_.repeatTimes),
79	        static_cast<uint64_t>(param_.dstBlockStride),
80	        static_cast<uint64_t>(param_.dstRepeatStride),
81	        false};
82	    // check dst src0 and src1 tensor overflow
83	    if (apiName == "Compare" || apiName == "Compare operator") {
84	        ASCENDC_CHECK(CheckCmpTensorOverflowLowNorm(params, "dstLocal"));
85	    } else {
86	        ASCENDC_CHECK(CheckTensorOverflowLow(maskArray, params, "dstLocal"));
87	    }
88	    params = {
89	        param_.src0Size,
90	        param_.src0DtypeBytes,
91	        static_cast<uint64_t>(param_.repeatTimes),
92	        static_cast<uint64_t>(param_.src0BlockStride),
93	        static_cast<uint64_t>(param_.src0RepeatStride),
94	        false};
95	    ASCENDC_CHECK(CheckTensorOverflowLow(maskArray, params, "src0Local"));
96	    params = {
97	        param_.src1Size,
98	        param_.src1DtypeBytes,
99	        static_cast<uint64_t>(param_.repeatTimes),
100	        static_cast<uint64_t>(param_.src1BlockStride),
101	        static_cast<uint64_t>(param_.src1RepeatStride),
102	        false};
103	    ASCENDC_CHECK(CheckTensorOverflowLow(maskArray, params, "src1Local"));
104	
105	    return true;
106	}
107	
108	bool TikcppVecBinaryCheck::CheckAllHighLevel()
109	{
110	    ASCENDC_CHECK(CommonCheck());
111	
112	    if (apiName == "Compare" || apiName == "Compare operator") {
113	        ASCENDC_CHECK(CheckCmpTensorOverflowHigh(param_.dstDtypeBytes, param_.dstSize, param_.calCount, "dstLocal"));
114	    } else {
115	        ASCENDC_CHECK(CheckTensorOverflowHigh(param_.dstDtypeBytes, param_.dstSize, param_.calCount, "dstLocal"));
116	    }
117	    ASCENDC_CHECK(CheckTensorOverflowHigh(param_.src0DtypeBytes, param_.src0Size, param_.calCount, "src0Local"));
118	    ASCENDC_CHECK(CheckTensorOverflowHigh(param_.src1DtypeBytes, param_.src1Size, param_.calCount, "src1Local"));
119	    return true;
120	}
121	
122	bool TikcppVecBinaryCheck::CheckAddrAlign()
123	{
124	    bool dstRes = CheckTensorAddrAlign(param_.dstAddr, param_.dstPos, ONE_BLK_SIZE, "dst");
125	    bool src0Res = CheckTensorAddrAlign(param_.src0Addr, param_.src0Pos, ONE_BLK_SIZE, "src0");
126	    bool src1Res = CheckTensorAddrAlign(param_.src1Addr, param_.src1Pos, ONE_BLK_SIZE, "src1");
127	    return dstRes && src0Res && src1Res;
128	}
